  ('d27', 'simplex', '2081-9044', 'SS', 'Protección contra sobretensiones (SS)', 'PROTECCIÓN CONTRA SOBRETENSIONES — SLC Y COMUNICACIÓN COBRE', 0, 0, 'SLC', 'Simbología CDCLH-001S: 2081-9044 es protección SLC/COM (en el Excel original figuraba como resistencia fin de línea). Sin consumo apreciable.', 26),
  ('d28', 'simplex', 'BASE SONORA', 'SB', 'Base audible (SB)', 'DETECTOR + BASE SONORA (habitaciones)', 1, 130, 'FUENTE AUX', 'Valor histórico Sinergia. Verificar ficha de base sonora usada', 27),
  ('d64', 'simplex', '4098-9601', 'SDH-C', 'Detector de humo convencional', 'DETECTOR DE HUMO FOTOELÉCTRICO CONVENCIONAL', 0.1, 0.1, 'ZONA', 'Ficha S4098-0015 Rev.6: reposo 100 µA. Alarma de ficha: 86 mA máx. (2 hilos, la limita el IDC) / 24 mA típ. (4 hilos). En zona convencional la corriente de alarma la fija el panel o módulo de zona: se cuenta aquí el reposo y la alarma de zona va en el equipo.', 28),
  ('d65', 'simplex', '4098-9613', 'SDT-C', 'Detector térmico convencional', 'DETECTOR TÉRMICO CONVENCIONAL 57.5 °C (135 °F)', 0.08, 0.08, 'ZONA', 'Reposo 80 µA típ. según instrucciones 574-686 y manual 574-709 (documentos antiguos de la familia térmica 4098); la ficha propia S4098-0014 no se pudo abrir: CONFIRMAR. La alarma (40–48 mA típ.) la limita el panel o módulo de zona.', 29),
  ('d66', 'simplex', '4098-9019', 'BH', 'Detector de humo de haz de luz (BT/BR)', 'DETECTOR DE HUMO DE HAZ DE LUZ (TRANSMISOR BT + RECEPTOR BR)', 50, 50, 'SLC', 'Ficha S4098-0049 Rev.1: alimentación 50 mA a 14–36 VDC desde fuente aparte (no distingue reposo y alarma). OJO: la ficha corresponde al sistema reflectivo 4098-9020 + cabezal 5000-031; no es un par transmisor BT / receptor BR: CONFIRMAR el modelo.', 30),
  ('d67', 'simplex', '4098-9771', 'CO+SB', 'Detector humo/CO con base audible (SB/CO)', 'BASE AUDIBLE CON DETECCIÓN DE CO 4098-9771 (solo la base; agregue el detector)', 1, 18, 'SLC', 'Ficha S4098-0052 Rev.4: sonador 17 mA a 24 VDC (24 mA a 32 V) en alarma + lazo IDNet 1 mA típ. La ficha no da reposo del lado 24 VDC; se usa el lazo (1 mA). Solo la base: agregue también el detector 4098-9714.', 31),
  ('d68', 'simplex', '4098-9794', 'SB', 'Base audible (SB)', 'BASE AUDIBLE PARA DETECTOR DIRECCIONABLE 4098-9794 (solo la base; agregue el detector)', 1, 21, 'FUENTE AUX', 'Ficha S4098-0028 Rev.11: sonador 20 mA a 24 VDC (24 mA a 32 V) en alarma + lazo IDNet 1 mA típ. La ficha no da reposo del lado 24 VDC; se usa el lazo (1 mA). Solo la base: agregue también el detector.', 32),
  ('d69', 'simplex', '4098-9772', 'SB', 'Base audible (SB)', 'BASE AUDIBLE 520 Hz 4098-9772 (solo la base; agregue el detector)', 1, 139, 'FUENTE AUX', 'Ficha S4098-0054 Rev.5: la ficha da la alarma solo a 16 V y 18 V (129–139 mA a 16 V; 115–125 mA a 18 V), no a 24 V. Se usa el peor caso (139 mA a 16 V), que cubre las dos señales; a 24 V será menor: CONFIRMAR con la Rev.8 de la ficha. Lazo 1 mA típ. Solo la base: agregue también el detector.', 33),
  ('d70', 'simplex', '2098-9806', 'RTS', 'Estación remota de prueba (detector de ducto)', 'ESTACIÓN REMOTA DE PRUEBA Y RESETEO PARA DETECTOR DE DUCTO', null, null, 'SLC', 'Sin ficha eléctrica publicada (solo listados de distribuidores). Corriente sin definir: consultar la ficha del detector de ducto 4098-9755 o de la estación.', 34),
  ('d71', 'simplex', '4099-9006', 'EM', 'Estación manual', 'ESTACIÓN MANUAL DIRECCIONABLE DOBLE ACCIÓN', null, null, 'SLC', 'Ficha S4099-0005 Rev.4: alimentación y datos por el lazo IDNet; no publica corriente. Corriente sin definir: usar la carga de lazo (unidades de carga IDNet) del panel (instrucciones 579-1135).', 35),
  ('d72', 'simplex', '4099-9006SP', 'EM', 'Estación manual', 'ESTACIÓN MANUAL DIRECCIONABLE DOBLE ACCIÓN (ESPAÑOL)', null, null, 'SLC', 'Ficha S4099-0005 Rev.4: alimentación y datos por el lazo IDNet; no publica corriente. Corriente sin definir: usar la carga de lazo (unidades de carga IDNet) del panel (instrucciones 579-1135).', 36),
  ('d73', 'simplex', '4906-9128', 'AV-C 15cd', 'Sirena + estrobo de cielo', 'SIRENA + ESTROBO DE CIELO TrueAlert 49AV-APPLC (4906-9128) 15 cd', 0.8, 67, 'NAC', 'Ficha S49AVC-0001 Rev.16: máx. RMS en IDNAC 23–30 VDC; reposo 0.8 mA (1 unidad de carga de supervisión). La ficha lista 49AV-APPLC, no el código 4906-9128 (equivalencia por listados de distribuidores): CONFIRMAR.', 37),
  ('d74', 'simplex', '4904-9183', 'ST-C-WRF 15cd', 'Estrobo de cielo direccionable', 'ESTROBO DE CIELO DIRECCIONABLE 49VO-APPLC (4904-9183) 15 cd', 0.8, 60, 'IDNAC', 'Ficha S4906-0004 Rev.5 (estrobos de cielo direccionables 4906-9202 / 4906-9204): IDNAC 23 VDC RMS, 23–31 V; reposo 0.8 mA (1 unidad de carga). La ficha no lista el código 4904-9183 ni 49VO-APPLC: CONFIRMAR la equivalencia.', 38),
  ('d75', 'simplex', '4603-9101', 'ANN', 'Anunciador remoto (FAA)', 'ANUNCIADOR REMOTO (FAA) — 24VDC, 6x14 STP', 65, 140, 'RED/24VDC', 'Ficha S4603-0001-14 (8/2016): 18–32 VDC. Reposo en baterías 65 mA (110 mA con iluminación en operación normal); alarma 140 mA máx.', 39),
  ('d76', 'simplex', '4100-9601', 'TRP', 'Transponder (TRP)', 'TRANSPONDER MODO LOCAL (4100-9601)', 112, 112, 'SISTEMA', 'Ficha S4100-0103 Rev.11: 4100-9601 en modo local 112 mA (87 mA en modo normal), igual en supervisión y alarma. OJO: el 4100-9600 del catálogo original figura con 425 / 735 mA y la ficha da 87 mA para el módulo transponder: REVISAR ese dato.', 40),
  ('d77', 'simplex', '4009-9201', 'RPS', 'Fuente de poder remota (RPS)', 'FUENTE REMOTA 24VDC 8A — NAC CONVENCIONAL', 85, 185, 'FUENTE AUX', 'Ficha S4009-0002-14 (9/2015), cálculo de baterías a 24 VDC: panel básico 85 mA en supervisión y 185 mA en alarma; cada módulo NAC adicional 4009-9807 suma +40 / +40 mA; salida auxiliar hasta 500 mA aparte. Baterías hasta 12.7 Ah (18 Ah en gabinete externo).', 41),
  ('d78', 'simplex', '4009-9401', 'RPS', 'Fuente de poder remota (RPS)', 'FUENTE REMOTA 24VDC 8A — NAC DIRECCIONABLE', null, null, 'FUENTE AUX', 'Código 4009-9401 sin ficha encontrada. Corriente sin definir: pedir a Simplex/JCI la ficha del P/N 4009-9401.', 42),
  ('d79', 'simplex', '4009-9601', 'RPS', 'Fuente de poder remota (RPS)', 'FUENTE REMOTA 24VDC 8A — IDNAC', 70, 96, 'FUENTE AUX', 'Ficha S4009-0004 Rev.6, tabla de baterías a 24 VDC: 70 mA propios en reposo (+0.8 mA por cada dispositivo IDNAC) y 96 mA propios en alarma (+1.37 × la corriente de carga IDNAC y +1.37 × la auxiliar). Los valores cargados son solo el consumo propio: sume la carga de los dispositivos IDNAC. Baterías hasta 12.7 Ah (25 Ah con gabinete 4009-9801).', 43),
